# C++ Qt5 Program to Convert Excel Files to CSV

Here's a complete C++ program using Qt5 that:
1. Opens a file dialog to select a directory
2. Creates a new "CSV_Output" folder in that directory
3. Converts all Excel files (.xlsx, .xls) to CSV format
4. Saves the CSV files in the output folder

```cpp
#include <QApplication>
#include <QFileDialog>
#include <QDir>
#include <QMessageBox>
#include <QDebug>
#include <QAxObject>
#include <QProgressDialog>

class ExcelToCsvConverter : public QObject {
    Q_OBJECT

public:
    ExcelToCsvConverter(QObject *parent = nullptr) : QObject(parent) {}

    void convertDirectory(const QString &dirPath) {
        QDir directory(dirPath);
        if (!directory.exists()) {
            QMessageBox::critical(nullptr, "Error", "Selected directory does not exist!");
            return;
        }

        // Create output directory
        QString outputDirPath = dirPath + "/CSV_Output";
        QDir outputDir(outputDirPath);
        if (!outputDir.exists()) {
            if (!outputDir.mkpath(".")) {
                QMessageBox::critical(nullptr, "Error", "Failed to create output directory!");
                return;
            }
        }

        // Get all Excel files in directory
        QStringList filters;
        filters << "*.xlsx" << "*.xls";
        QStringList excelFiles = directory.entryList(filters, QDir::Files);

        if (excelFiles.isEmpty()) {
            QMessageBox::information(nullptr, "Information", "No Excel files found in the selected directory.");
            return;
        }

        // Initialize Excel application
        QAxObject *excel = new QAxObject("Excel.Application", this);
        if (!excel) {
            QMessageBox::critical(nullptr, "Error", "Failed to initialize Excel application!");
            return;
        }

        // Show progress dialog
        QProgressDialog progress("Converting Excel files to CSV...", "Cancel", 0, excelFiles.size());
        progress.setWindowModality(Qt::WindowModal);
        progress.setMinimumDuration(0);

        int successCount = 0;
        int errorCount = 0;

        for (int i = 0; i < excelFiles.size(); ++i) {
            progress.setValue(i);
            if (progress.wasCanceled()) {
                break;
            }

            QString excelFilePath = dirPath + "/" + excelFiles[i];
            QString csvFilePath = outputDirPath + "/" + excelFiles[i].left(excelFiles[i].lastIndexOf('.')) + ".csv";

            if (convertExcelToCsv(excel, excelFilePath, csvFilePath)) {
                successCount++;
            } else {
                errorCount++;
            }
        }

        // Clean up
        excel->dynamicCall("Quit()");
        delete excel;

        progress.setValue(excelFiles.size());

        // Show results
        QString message = QString("Conversion complete!\n\n"
                                 "Successfully converted: %1 files\n"
                                 "Failed to convert: %2 files").arg(successCount).arg(errorCount);
        QMessageBox::information(nullptr, "Results", message);
    }

private:
    bool convertExcelToCsv(QAxObject *excel, const QString &excelFilePath, const QString &csvFilePath) {
        try {
            // Open the workbook
            QAxObject *workbooks = excel->querySubObject("Workbooks");
            QAxObject *workbook = workbooks->querySubObject("Open(const QString&)", excelFilePath);

            if (!workbook) {
                qWarning() << "Failed to open workbook:" << excelFilePath;
                return false;
            }

            // Get the first worksheet
            QAxObject *worksheets = workbook->querySubObject("Worksheets");
            QAxObject *worksheet = worksheets->querySubObject("Item(int)", 1);

            if (!worksheet) {
                qWarning() << "Failed to get worksheet from workbook:" << excelFilePath;
                workbook->dynamicCall("Close()");
                return false;
            }

            // Save as CSV
            QAxObject *usedRange = worksheet->querySubObject("UsedRange");
            if (!usedRange) {
                qWarning() << "Failed to get used range from worksheet:" << excelFilePath;
                workbook->dynamicCall("Close()");
                return false;
            }

            // Save the CSV file
            worksheet->dynamicCall("SaveAs(const QString&, int)", csvFilePath, 6); // 6 = xlCSV

            // Close the workbook
            workbook->dynamicCall("Close()");

            return true;
        } catch (...) {
            qWarning() << "Exception occurred while converting:" << excelFilePath;
            return false;
        }
    }
};

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);

    // Set up the main window (minimal)
    QWidget window;
    window.setWindowTitle("Excel to CSV Converter");
    window.resize(300, 100);

    // Create a button to select directory
    QPushButton button("Select Directory", &window);
    button.setGeometry(50, 30, 200, 40);

    ExcelToCsvConverter converter;

    QObject::connect(&button, &QPushButton::clicked, [&]() {
        QString dirPath = QFileDialog::getExistingDirectory(nullptr, "Select Directory", QDir::homePath());
        if (!dirPath.isEmpty()) {
            converter.convertDirectory(dirPath);
        }
    });

    window.show();
    return app.exec();
}

#include "main.moc"
```

## How to Compile and Run

1. Make sure you have Qt5 installed with the ActiveQt module (for Excel automation)
2. Create a project file (e.g., `excel_to_csv.pro`):

```qmake
QT += widgets axcontainer
TARGET = ExcelToCsvConverter
SOURCES = main.cpp
```

3. Compile with:
```bash
qmake excel_to_csv.pro
make
```

4. Run the executable

## Notes

1. This code requires Microsoft Excel to be installed on the system.
2. The program uses ActiveX to control Excel, which is Windows-specific.
3. For Linux/macOS, you would need to use a different approach (like LibreOffice or a library like QtXlsx).
4. The conversion might take some time for large Excel files.
5. The program creates a "CSV_Output" folder in the selected directory for the converted files.

